40	/**
41	 * Checks to see if datanodes have finished DECOMMISSION_INPROGRESS or
42	 * ENTERING_MAINTENANCE state.
43	 * <p>
44	 * Since this is done while holding the namesystem lock,
45	 * the amount of work per monitor tick is limited.
46	 */
47	
48	public class DatanodeAdminDefaultMonitor extends DatanodeAdminMonitorBase
49	    implements DatanodeAdminMonitorInterface {
50	
51	  /**
52	   * Map containing the DECOMMISSION_INPROGRESS or ENTERING_MAINTENANCE
53	   * datanodes that are being tracked so they can be be marked as
54	   * DECOMMISSIONED or IN_MAINTENANCE. Even after the node is marked as
55	   * IN_MAINTENANCE, the node remains in the map until
56	   * maintenance expires checked during a monitor tick.
57	   * <p/>
58	   * This holds a set of references to the under-replicated blocks on the DN
59	   * at the time the DN is added to the map, i.e. the blocks that are
60	   * preventing the node from being marked as decommissioned. During a monitor
61	   * tick, this list is pruned as blocks becomes replicated.
62	   * <p/>
63	   * Note also that the reference to the list of under-replicated blocks
64	   * will be null on initial add
65	   * <p/>
66	   * However, this map can become out-of-date since it is not updated by block
67	   * reports or other events. Before being finally marking as decommissioned,
68	   * another check is done with the actual block map.
69	   */
70	  private final TreeMap<DatanodeDescriptor, AbstractList<BlockInfo>>
71	      outOfServiceNodeBlocks;
72	
73	  /**
74	   * The maximum number of blocks to check per tick.
75	   */
76	  private int numBlocksPerCheck;
77	
78	  /**
79	   * The number of blocks that have been checked on this tick.
80	   */
81	  private int numBlocksChecked = 0;
82	  /**
83	   * The number of blocks checked after (re)holding lock.
84	   */
85	  private int numBlocksCheckedPerLock = 0;
86	  /**
87	   * The number of nodes that have been checked on this tick. Used for
88	   * statistics.
89	   */
90	  private int numNodesChecked = 0;
91	  /**
92	   * The last datanode in outOfServiceNodeBlocks that we've processed.
93	   */
94	  private DatanodeDescriptor iterkey = new DatanodeDescriptor(
95	      new DatanodeID("", "", "", 0, 0, 0, 0));
96	
97	  private static final Logger LOG =
98	      LoggerFactory.getLogger(DatanodeAdminDefaultMonitor.class);
99	
100	  DatanodeAdminDefaultMonitor() {
101	    this.outOfServiceNodeBlocks = new TreeMap<>();
102	  }
103	
104	  @Override
105	  protected void processConf() {
106	    numBlocksPerCheck = conf.getInt(
107	        DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_KEY,
108	        DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_DEFAULT);
109	    if (numBlocksPerCheck <= 0) {
110	      LOG.error("{} must be greater than zero. Defaulting to {}",
111	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_KEY,
112	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_DEFAULT);
113	      numBlocksPerCheck =
114	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_DEFAULT;
115	    }
116	    LOG.info("Initialized the Default Decommission and Maintenance monitor");
117	  }
118	
119	  private boolean exceededNumBlocksPerCheck() {
120	    LOG.trace("Processed {} blocks so far this tick", numBlocksChecked);
121	    return numBlocksChecked >= numBlocksPerCheck;
122	  }
123	
124	  @Override
125	  public void stopTrackingNode(DatanodeDescriptor dn) {
126	    getPendingNodes().remove(dn);
127	    outOfServiceNodeBlocks.remove(dn);
128	  }
129	
130	  @Override
131	  public int getTrackedNodeCount() {
132	    return outOfServiceNodeBlocks.size();
133	  }
134	
135	  @Override
136	  public int getNumNodesChecked() {
137	    return numNodesChecked;
138	  }
139	
140	  @Override
141	  public void run() {
142	    LOG.debug("DatanodeAdminMonitor is running.");
143	    if (!namesystem.isRunning()) {
144	      LOG.info("Namesystem is not running, skipping " +
145	          "decommissioning/maintenance checks.");
146	      return;
147	    }
148	    // Reset the checked count at beginning of each iteration
149	    numBlocksChecked = 0;
150	    numBlocksCheckedPerLock = 0;
151	    numNodesChecked = 0;
152	    // Check decommission or maintenance progress.
153	    namesystem.writeLock();
154	    try {
155	      processPendingNodes();
156	      check();
157	    } catch (Exception e) {
158	      LOG.warn("DatanodeAdminMonitor caught exception when processing node.",
159	          e);
160	    } finally {
161	      namesystem.writeUnlock();
162	    }
163	    if (numBlocksChecked + numNodesChecked > 0) {
164	      LOG.info("Checked {} blocks and {} nodes this tick. {} nodes are now " +
165	              "in maintenance or transitioning state. {} nodes pending.",
166	          numBlocksChecked, numNodesChecked, outOfServiceNodeBlocks.size(),
167	          getPendingNodes().size());
168	    }
169	  }
170	
171	  /**
172	   * Pop datanodes off the pending priority queue and into decomNodeBlocks,
173	   * subject to the maxConcurrentTrackedNodes limit.
174	   */
175	  private void processPendingNodes() {
176	    while (!getPendingNodes().isEmpty() &&
177	        (maxConcurrentTrackedNodes == 0 ||
178	            outOfServiceNodeBlocks.size() < maxConcurrentTrackedNodes)) {
179	      outOfServiceNodeBlocks.put(getPendingNodes().poll(), null);
180	    }
181	  }
182	
183	  private void check() {
184	    final Iterator<Map.Entry<DatanodeDescriptor, AbstractList<BlockInfo>>>
185	        it = new CyclicIteration<>(outOfServiceNodeBlocks,
186	        iterkey).iterator();
187	    final List<DatanodeDescriptor> toRemove = new ArrayList<>();
188	    final List<DatanodeDescriptor> unhealthyDns = new ArrayList<>();
189	
190	    while (it.hasNext() && !exceededNumBlocksPerCheck() && namesystem
191	        .isRunning()) {
192	      numNodesChecked++;
193	      final Map.Entry<DatanodeDescriptor, AbstractList<BlockInfo>>
194	          entry = it.next();
195	      final DatanodeDescriptor dn = entry.getKey();
196	      try {
197	        AbstractList<BlockInfo> blocks = entry.getValue();
198	        boolean fullScan = false;
199	        if (dn.isMaintenance() && dn.maintenanceExpired()) {
200	          // If maintenance expires, stop tracking it.
201	          dnAdmin.stopMaintenance(dn);
202	          toRemove.add(dn);
203	          continue;
204	        }
205	        if (dn.isInMaintenance()) {
206	          // The dn is IN_MAINTENANCE and the maintenance hasn't expired yet.
207	          continue;
208	        }
209	        if (blocks == null) {
210	          // This is a newly added datanode, run through its list to schedule
211	          // under-replicated blocks for replication and collect the blocks
212	          // that are insufficiently replicated for further tracking
213	          LOG.debug("Newly-added node {}, doing full scan to find " +
214	              "insufficiently-replicated blocks.", dn);
215	          blocks = handleInsufficientlyStored(dn);
216	          outOfServiceNodeBlocks.put(dn, blocks);
217	          fullScan = true;
218	        } else {
219	          // This is a known datanode, check if its # of insufficiently
220	          // replicated blocks has dropped to zero and if it can move
221	          // to the next state.
222	          LOG.debug("Processing {} node {}", dn.getAdminState(), dn);
223	          pruneReliableBlocks(dn, blocks);
224	        }
225	        final boolean isHealthy = blockManager.isNodeHealthyForDecommissionOrMaintenance(dn);
226	        if (!isHealthy) {
227	          unhealthyDns.add(dn);
228	        }
229	        if (blocks.size() == 0) {
230	          if (!fullScan) {
231	            // If we didn't just do a full scan, need to re-check with the
232	            // full block map.
233	            //
234	            // We've replicated all the known insufficiently replicated
235	            // blocks. Re-check with the full block map before finally
236	            // marking the datanode as DECOMMISSIONED or IN_MAINTENANCE.
237	            LOG.debug("Node {} has finished replicating current set of "
238	                + "blocks, checking with the full block map.", dn);
239	            blocks = handleInsufficientlyStored(dn);
240	            outOfServiceNodeBlocks.put(dn, blocks);
241	          }
242	          // If the full scan is clean AND the node liveness is okay,
243	          // we can finally mark as DECOMMISSIONED or IN_MAINTENANCE.
244	          if (blocks.size() == 0 && isHealthy) {
245	            if (dn.isDecommissionInProgress()) {
246	              dnAdmin.setDecommissioned(dn);
247	              toRemove.add(dn);
248	            } else if (dn.isEnteringMaintenance()) {
249	              // IN_MAINTENANCE node remains in the outOfServiceNodeBlocks to
250	              // to track maintenance expiration.
251	              dnAdmin.setInMaintenance(dn);
252	            } else {
253	              Preconditions.checkState(false,
254	                  "Node %s is in an invalid state! "
255	                      + "Invalid state: %s %s blocks are on this dn.",
256	                  dn, dn.getAdminState(), blocks.size());
257	            }
258	            LOG.debug("Node {} is sufficiently replicated and healthy, "
259	                + "marked as {}.", dn, dn.getAdminState());
260	          } else {
261	            LOG.info("Node {} {} healthy."
262	                    + " It needs to replicate {} more blocks."
263	                    + " {} is still in progress.", dn,
264	                isHealthy ? "is": "isn't", blocks.size(), dn.getAdminState());
265	          }
266	        } else {
267	          LOG.info("Node {} still has {} blocks to replicate "
268	                  + "before it is a candidate to finish {}.",
269	              dn, blocks.size(), dn.getAdminState());
270	        }
271	      } catch (Exception e) {
272	        // Log and postpone to process node when meet exception since it is in
273	        // an invalid state.
274	        LOG.warn("DatanodeAdminMonitor caught exception when processing node "
275	            + "{}.", dn, e);
276	        getPendingNodes().add(dn);
277	        toRemove.add(dn);
278	      } finally {
279	        iterkey = dn;
280	      }
281	    }
282	
283	    // Having more nodes decommissioning than can be tracked will impact decommissioning
284	    // performance due to queueing delay
285	    int numTrackedNodes = outOfServiceNodeBlocks.size() - toRemove.size();
286	    int numQueuedNodes = getPendingNodes().size();
287	    int numDecommissioningNodes = numTrackedNodes + numQueuedNodes;
288	    if (numDecommissioningNodes > maxConcurrentTrackedNodes) {
289	      LOG.warn(
290	          "{} nodes are decommissioning but only {} nodes will be tracked at a time. "
291	              + "{} nodes are currently queued waiting to be decommissioned.",
292	          numDecommissioningNodes, maxConcurrentTrackedNodes, numQueuedNodes);
293	
294	      // Re-queue unhealthy nodes to make space for decommissioning healthy nodes
295	      getUnhealthyNodesToRequeue(unhealthyDns, numDecommissioningNodes).forEach(dn -> {
296	        getPendingNodes().add(dn);
297	        outOfServiceNodeBlocks.remove(dn);
298	      });
299	    }
300	
301	    // Remove the datanodes that are DECOMMISSIONED or in service after
302	    // maintenance expiration.
303	    for (DatanodeDescriptor dn : toRemove) {
304	      Preconditions.checkState(dn.isDecommissioned() || dn.isInService(),
305	          "Removing node %s that is not yet decommissioned or in service!",
306	          dn);
307	      outOfServiceNodeBlocks.remove(dn);
308	    }
309	  }
310	
311	  /**
312	   * Removes reliable blocks from the block list of a datanode.
313	   */
314	  private void pruneReliableBlocks(final DatanodeDescriptor datanode,
315	                                   AbstractList<BlockInfo> blocks) {
316	    processBlocksInternal(datanode, blocks.iterator(), null, true);
317	  }
318	
319	  /**
320	   * Returns a list of blocks on a datanode that are insufficiently
321	   * replicated or require recovery, i.e. requiring recovery and
322	   * should prevent decommission or maintenance.
323	   * <p/>
324	   * As part of this, it also schedules replication/recovery work.
325	   *
326	   * @return List of blocks requiring recovery
327	   */
328	  private AbstractList<BlockInfo> handleInsufficientlyStored(
329	      final DatanodeDescriptor datanode) {
330	    AbstractList<BlockInfo> insufficient = new ChunkedArrayList<>();
331	    processBlocksInternal(datanode, datanode.getBlockIterator(),
332	        insufficient, false);
333	    return insufficient;
334	  }
