336	  /**
337	   * Used while checking if DECOMMISSION_INPROGRESS datanodes can be
338	   * marked as DECOMMISSIONED or ENTERING_MAINTENANCE datanodes can be
339	   * marked as IN_MAINTENANCE. Combines shared logic of pruneReliableBlocks
340	   * and handleInsufficientlyStored.
341	   *
342	   * @param datanode                    Datanode
343	   * @param it                          Iterator over the blocks on the
344	   *                                    datanode
345	   * @param insufficientList            Return parameter. If it's not null,
346	   *                                    will contain the insufficiently
347	   *                                    replicated-blocks from the list.
348	   * @param pruneReliableBlocks         whether to remove blocks reliable
349	   *                                    enough from the iterator
350	   */
351	  private void processBlocksInternal(
352	      final DatanodeDescriptor datanode,
353	      final Iterator<BlockInfo> it,
354	      final List<BlockInfo> insufficientList,
355	      boolean pruneReliableBlocks) {
356	    boolean firstReplicationLog = true;
357	    // Low redundancy in UC Blocks only
358	    int lowRedundancyBlocksInOpenFiles = 0;
359	    LightWeightHashSet<Long> lowRedundancyOpenFiles =
360	        new LightWeightLinkedSet<>();
361	    // All low redundancy blocks. Includes lowRedundancyOpenFiles.
362	    int lowRedundancyBlocks = 0;
363	    // All maintenance and decommission replicas.
364	    int outOfServiceOnlyReplicas = 0;
365	    while (it.hasNext()) {
366	      if (insufficientList == null
367	          && numBlocksCheckedPerLock >= numBlocksPerCheck) {
368	        // During fullscan insufficientlyReplicated will NOT be null, iterator
369	        // will be DN's iterator. So should not yield lock, otherwise
370	        // ConcurrentModificationException could occur.
371	        // Once the fullscan done, iterator will be a copy. So can yield the
372	        // lock.
373	        // Yielding is required in case of block number is greater than the
374	        // configured per-iteration-limit.
375	        namesystem.writeUnlock();
376	        try {
377	          LOG.debug("Yielded lock during decommission/maintenance check");
378	          Thread.sleep(0, 500);
379	        } catch (InterruptedException ignored) {
380	          return;
381	        }
382	        // reset
383	        numBlocksCheckedPerLock = 0;
384	        namesystem.writeLock();
385	      }
386	      numBlocksChecked++;
387	      numBlocksCheckedPerLock++;
388	      final BlockInfo block = it.next();
389	      // Remove the block from the list if it's no longer in the block map,
390	      // e.g. the containing file has been deleted
391	      if (blockManager.blocksMap.getStoredBlock(block) == null) {
392	        LOG.trace("Removing unknown block {}", block);
393	        it.remove();
394	        continue;
395	      }
396	
397	      long bcId = block.getBlockCollectionId();
398	      if (bcId == INodeId.INVALID_INODE_ID) {
399	        // Orphan block, will be invalidated eventually. Skip.
400	        continue;
401	      }
402	
403	      final BlockCollection bc = blockManager.getBlockCollection(block);
404	      final NumberReplicas num = blockManager.countNodes(block);
405	      final int liveReplicas = num.liveReplicas();
406	
407	      // Schedule low redundancy blocks for reconstruction
408	      // if not already pending.
409	      boolean isDecommission = datanode.isDecommissionInProgress();
410	      boolean isMaintenance = datanode.isEnteringMaintenance();
411	      boolean neededReconstruction = isDecommission ?
412	          blockManager.isNeededReconstruction(block, num) :
413	          blockManager.isNeededReconstructionForMaintenance(block, num);
414	      if (neededReconstruction) {
415	        if (!blockManager.neededReconstruction.contains(block) &&
416	            blockManager.pendingReconstruction.getNumReplicas(block) == 0 &&
417	            blockManager.isPopulatingReplQueues()) {
418	          // Process these blocks only when active NN is out of safe mode.
419	          blockManager.neededReconstruction.add(block,
420	              liveReplicas, num.readOnlyReplicas(),
421	              num.outOfServiceReplicas(),
422	              blockManager.getExpectedRedundancyNum(block));
423	        }
424	      }
425	
426	      // Even if the block is without sufficient redundancy,
427	      // it might not block decommission/maintenance if it
428	      // has sufficient redundancy.
429	      if (dnAdmin.isSufficient(block, bc, num, isDecommission, isMaintenance)) {
430	        if (pruneReliableBlocks) {
431	          it.remove();
432	        }
433	        continue;
434	      }
435	
436	      // We've found a block without sufficient redundancy.
437	      if (insufficientList != null) {
438	        insufficientList.add(block);
439	      }
440	      // Log if this is our first time through
441	      if (firstReplicationLog) {
442	        dnAdmin.logBlockReplicationInfo(block, bc, datanode, num,
443	            blockManager.blocksMap.getStorages(block));
444	        firstReplicationLog = false;
445	      }
446	      // Update various counts
447	      lowRedundancyBlocks++;
448	      if (bc.isUnderConstruction()) {
449	        INode ucFile = namesystem.getFSDirectory().getInode(bc.getId());
450	        if (!(ucFile instanceof INodeFile) ||
451	            !ucFile.asFile().isUnderConstruction()) {
452	          LOG.warn("File {} is not under construction. Skipping add to " +
453	              "low redundancy open files!", ucFile.getLocalName());
454	        } else {
455	          lowRedundancyBlocksInOpenFiles++;
456	          lowRedundancyOpenFiles.add(ucFile.getId());
457	        }
458	      }
459	      if ((liveReplicas == 0) && (num.outOfServiceReplicas() > 0)) {
460	        outOfServiceOnlyReplicas++;
461	      }
462	    }
463	
464	    datanode.getLeavingServiceStatus().set(lowRedundancyBlocksInOpenFiles,
465	        lowRedundancyOpenFiles, lowRedundancyBlocks,
466	        outOfServiceOnlyReplicas);
467	  }
