180	      final int numUnhealthyNodesToRequeue =
181	          Math.min(numDecommissioningNodes - maxConcurrentTrackedNodes, unhealthyDns.size());
182	
183	      LOG.warn("{} limit has been reached, re-queueing {} "
184	              + "nodes which are dead while in Decommission In Progress.",
185	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_MAX_CONCURRENT_TRACKED_NODES,
186	          numUnhealthyNodesToRequeue);
187	
188	      // Order unhealthy nodes by lastUpdate descending such that nodes
189	      // which have been unhealthy the longest are preferred to be re-queued
190	      return unhealthyDns.stream().sorted(PENDING_NODES_QUEUE_COMPARATOR.reversed())
