 */
private void processPendingNodes() {
  while (!getPendingNodes().isEmpty() &&
      (maxConcurrentTrackedNodes == 0 ||
          outOfServiceNodeBlocks.size() < maxConcurrentTrackedNodes)) {
    outOfServiceNodeBlocks.put(getPendingNodes().poll(), null);
  }
}

/**
 * Remove the nodes which have had their decommission or maintenance
 * cancelled from the tracked node map.
 * <p/>
 * The nodes are queued by stopTrackingNode() and removed here rather than
 * being removed as soon as they are cancelled, as removing an entry from
 * the tracked node map while check() is iterating over it can leave the
 * iterator looping forever, holding the namenode write lock.
 */
private void processCancelledNodes() {
  while (!cancelledNodes.isEmpty()) {
    DatanodeDescriptor dn = cancelledNodes.poll();
    outOfServiceNodeBlocks.remove(dn);
  }
}

