/**
 * Test that a node which has its decommission cancelled is not removed from
 * the set of tracked nodes until the start of the next monitor tick.
 * Removing a node from the tracked nodes while the monitor is iterating over
 * them can leave the monitor looping forever, holding the namenode write
 * lock.
 */
@Test(timeout=120000)
public void testCancelledNodesRemovedOnNextTick() throws Exception {
  // Disable the normal monitor runs, so it can be triggered on demand below
  getConf().setInt(
      MiniDFSCluster.DFS_NAMENODE_DECOMMISSION_INTERVAL_TESTING_KEY,
      Integer.MAX_VALUE);
  startCluster(1, 2);
  final FileSystem fs = getCluster().getFileSystem();
  final DatanodeManager datanodeManager =
      getCluster().getNamesystem().getBlockManager().getDatanodeManager();
  final DatanodeAdminManager decomManager =
      datanodeManager.getDatanodeAdminManager();

  // Write a file with a replica on each of the two datanodes, so that
  // decommission cannot complete, as there is nowhere to replicate to.
  final Path file = new Path("/testCancelledNodes.dat");
  writeFile(fs, file, 2);
  DFSTestUtil.waitReplication(fs, file, (short) 2);

  // Decommission a node and run the monitor, so the node is moved from the
  // pending queue into the set of tracked nodes.
  final DataNode d = getCluster().getDataNodes().get(0);
  final DatanodeInfo dn = takeNodeOutofService(0, d.getDatanodeUuid(), 0,
      null, AdminStates.DECOMMISSION_INPROGRESS);
  assertTrackedAndPending(decomManager, 0, 1);
  BlockManagerTestUtil.recheckDecommissionState(datanodeManager);
  assertTrackedAndPending(decomManager, 1, 0);

  // Cancelling the decommission must not remove the node from the tracked
  // nodes immediately, as the monitor may be iterating over them.
  putNodeInService(0, dn);
  assertTrackedAndPending(decomManager, 1, 0);

  // The cancelled node is removed from tracking by the next monitor tick.
  BlockManagerTestUtil.recheckDecommissionState(datanodeManager);
  assertTrackedAndPending(decomManager, 0, 0);

  cleanupFile(fs, file);
}

